#!/usr/bin/env node
/**
 * BEAN Intelligence — build the browser AI workers as self-hosted assets.
 *
 * The three heavy AI runtimes (@mlc-ai/web-llm, @huggingface/transformers,
 * onnxruntime-web) are ONLY used inside dedicated module workers. Bundling
 * them into the Next.js compile graph measurably OOM-kills the 4 GB build
 * sandbox (exit 137, measured repeatedly). This script bundles each worker
 * ONCE with bun's bundler into public/workers/ — same-origin, self-hosted,
 * no third-party CDN — and keeps them OUT of the Next graph entirely.
 *
 * Regenerated by `bun run build` / `bun run dev` / `bun run workers:build`.
 */
import { mkdirSync, existsSync, statSync, rmSync } from 'fs'
import { join } from 'path'
import { execFileSync } from 'child_process'

const root = process.cwd()
const outDir = join(root, 'public', 'workers')
const workerPkgDir = join(root, 'src', 'workers')

/** Ensure the nested worker-build-time dependencies exist (src/workers/
 * node_modules). The heavy browser runtimes deliberately live HERE, not in
 * the app's node_modules — see src/workers/package.json. */
function ensureWorkerDeps() {
  const marker = join(workerPkgDir, 'node_modules', 'onnxruntime-web')
  if (existsSync(marker)) return
  console.log('[workers-build] installing nested worker dependencies (first run)...')
  execFileSync('bun', ['install'], { stdio: 'inherit', cwd: workerPkgDir })
}

const WORKERS = [
  { src: 'src/workers/webllm-worker.ts', out: 'webllm-worker.js' },
  { src: 'src/workers/asr-worker.ts', out: 'asr-worker.js' },
  { src: 'src/workers/segmentation-worker.ts', out: 'segmentation-worker.js' },
]

mkdirSync(outDir, { recursive: true })
ensureWorkerDeps()

let ok = 0
for (const w of WORKERS) {
  const srcPath = join(root, w.src)
  if (!existsSync(srcPath)) {
    console.error(`[workers-build] missing source: ${w.src}`)
    process.exitCode = 1
    continue
  }
  const outPath = join(outDir, w.out)
  try {
    execFileSync(
      'bun',
      ['build', srcPath, '--outfile', outPath, '--format', 'esm', '--target', 'browser', '--minify'],
      { stdio: 'pipe', cwd: root, maxBuffer: 8 * 1024 * 1024 },
    )
    const size = statSync(outPath).size
    console.log(`[workers-build] ${w.out}: ${(size / 1024 / 1024).toFixed(2)} MB`)
    ok++
  } catch (error) {
    console.error(`[workers-build] FAILED for ${w.src}:`, error instanceof Error ? error.message.slice(0, 400) : error)
    process.exitCode = 1
  }
}
if (ok === WORKERS.length) console.log('[workers-build] all worker bundles up to date')
